CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 0. REMOÇÃO DE TABELAS ANTIGAS/INCOMPLETAS (PARA EVITAR ERRO DE COLUNAS FALTANTES)
---------------------------------------------------------------------------
DROP TABLE IF EXISTS public.planning_links CASCADE;
DROP TABLE IF EXISTS public.attachments CASCADE;
DROP TABLE IF EXISTS public.demand_updates CASCADE;
DROP TABLE IF EXISTS public.demands CASCADE;
DROP TABLE IF EXISTS public.planning_items CASCADE;
DROP TABLE IF EXISTS public.users CASCADE;
DROP TABLE IF EXISTS public.access_profiles CASCADE;
DROP TABLE IF EXISTS public.kanban_stages CASCADE;
DROP TABLE IF EXISTS public.priority_levels CASCADE;
DROP TABLE IF EXISTS public.categories CASCADE;
DROP TABLE IF EXISTS public.schools CASCADE;

-- 1. DDL DE CRIAÇÃO DAS TABELAS
---------------------------------------------------------------------------
-- Tabela: schools
CREATE TABLE public.schools (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    director TEXT,
    address TEXT,
    phone TEXT,
    email TEXT,
    code TEXT,
    external_id TEXT,
    lat DOUBLE PRECISION,
    lon DOUBLE PRECISION,
    active INTEGER NOT NULL DEFAULT 1
);

-- Tabela: users
CREATE TABLE public.users (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL,
    school_id BIGINT REFERENCES public.schools(id) ON DELETE SET NULL,
    active INTEGER NOT NULL DEFAULT 1
);

-- Tabela: access_profiles
CREATE TABLE public.access_profiles (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug TEXT UNIQUE NOT NULL,
    label TEXT NOT NULL,
    description TEXT,
    school_scoped INTEGER NOT NULL DEFAULT 0,
    can_edit_analysis INTEGER NOT NULL DEFAULT 1,
    can_manage_admin INTEGER NOT NULL DEFAULT 0,
    can_view_reports INTEGER NOT NULL DEFAULT 1,
    can_view_planning INTEGER NOT NULL DEFAULT 1,
    is_system INTEGER NOT NULL DEFAULT 0,
    active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP::text
);

-- Tabela: categories
CREATE TABLE public.categories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT UNIQUE NOT NULL,
    icon TEXT NOT NULL DEFAULT 'wrench',
    color TEXT NOT NULL DEFAULT 'blue',
    hint TEXT,
    sort_order INTEGER NOT NULL DEFAULT 0,
    active INTEGER NOT NULL DEFAULT 1
);

-- Tabela: priority_levels
CREATE TABLE public.priority_levels (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code TEXT UNIQUE NOT NULL,
    label TEXT NOT NULL,
    hint TEXT,
    color TEXT NOT NULL DEFAULT 'red',
    rank INTEGER NOT NULL
);

-- Tabela: kanban_stages
CREATE TABLE public.kanban_stages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    stage_key TEXT UNIQUE NOT NULL,
    label TEXT NOT NULL,
    hint TEXT,
    accent TEXT NOT NULL DEFAULT 'blue',
    statuses TEXT NOT NULL,
    target_status TEXT NOT NULL,
    sort_order INTEGER NOT NULL DEFAULT 0
);

-- Tabela: demands
CREATE TABLE public.demands (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code TEXT UNIQUE,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    category TEXT NOT NULL,
    subcategory TEXT,
    location TEXT,
    impact TEXT,
    affected_people INTEGER DEFAULT 0,
    risk INTEGER DEFAULT 0,
    blocks_activity INTEGER DEFAULT 0,
    school_id BIGINT NOT NULL REFERENCES public.schools(id) ON DELETE CASCADE,
    priority TEXT NOT NULL DEFAULT 'P3',
    status TEXT NOT NULL DEFAULT 'Nova',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    due_date TEXT,
    responsible TEXT,
    sector TEXT,
    cost_estimate DOUBLE PRECISION DEFAULT 0,
    action_defined TEXT,
    technical_opinion TEXT,
    dependencies TEXT,
    needs_visit INTEGER DEFAULT 0,
    needs_budget INTEGER DEFAULT 0,
    needs_material INTEGER DEFAULT 0,
    needs_contract INTEGER DEFAULT 0,
    future_year INTEGER,
    planning_kind TEXT,
    planned_quantity DOUBLE PRECISION DEFAULT 0,
    planned_unit TEXT,
    created_by BIGINT REFERENCES public.users(id) ON DELETE SET NULL,
    prov_description TEXT,
    prov_action_type TEXT,
    prov_responsible TEXT,
    prov_due_date TEXT,
    prov_priority TEXT,
    prov_note TEXT,
    prov_notify_school INTEGER NOT NULL DEFAULT 0
);

-- Tabela: demand_updates
CREATE TABLE public.demand_updates (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    demand_id BIGINT NOT NULL REFERENCES public.demands(id) ON DELETE CASCADE,
    kind TEXT NOT NULL,
    message TEXT NOT NULL,
    author TEXT NOT NULL,
    visibility TEXT NOT NULL DEFAULT 'public',
    created_at TEXT NOT NULL
);

-- Tabela: attachments
CREATE TABLE public.attachments (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    demand_id BIGINT NOT NULL REFERENCES public.demands(id) ON DELETE CASCADE,
    category TEXT,
    filename TEXT NOT NULL,
    stored_name TEXT NOT NULL,
    mime TEXT,
    size BIGINT DEFAULT 0,
    created_at TEXT NOT NULL
);

-- Tabela: planning_items
CREATE TABLE public.planning_items (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code TEXT UNIQUE,
    year INTEGER NOT NULL,
    title TEXT NOT NULL,
    category TEXT NOT NULL,
    kind TEXT NOT NULL,
    status TEXT NOT NULL,
    estimated_cost DOUBLE PRECISION DEFAULT 0,
    quantity DOUBLE PRECISION DEFAULT 0,
    unit TEXT,
    justification TEXT,
    schools_count INTEGER DEFAULT 1,
    process_number TEXT,
    procurement_number TEXT,
    contract_number TEXT,
    supplier TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

-- Tabela: planning_links
CREATE TABLE public.planning_links (
    planning_id BIGINT NOT NULL REFERENCES public.planning_items(id) ON DELETE CASCADE,
    demand_id BIGINT NOT NULL REFERENCES public.demands(id) ON DELETE CASCADE,
    PRIMARY KEY (planning_id, demand_id)
);

-- 2. POLÍTICAS DE SEGURANÇA (ROW LEVEL SECURITY - RLS)
---------------------------------------------------------------------------
ALTER TABLE public.schools ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Permitir acesso completo em schools" ON public.schools;
CREATE POLICY "Permitir acesso completo em schools" ON public.schools FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Permitir acesso completo em users" ON public.users;
CREATE POLICY "Permitir acesso completo em users" ON public.users FOR ALL USING (true) WITH CHECK (true);

