DROP POLICY IF EXISTS "Permitir acesso completo em priority_levels" ON public.priority_levels;
CREATE POLICY "Permitir acesso completo em priority_levels" ON public.priority_levels FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE public.kanban_stages ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Permitir acesso completo em kanban_stages" ON public.kanban_stages;
CREATE POLICY "Permitir acesso completo em kanban_stages" ON public.kanban_stages FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE public.demands ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Permitir acesso completo em demands" ON public.demands;
CREATE POLICY "Permitir acesso completo em demands" ON public.demands FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE public.demand_updates ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Permitir acesso completo em demand_updates" ON public.demand_updates;
CREATE POLICY "Permitir acesso completo em demand_updates" ON public.demand_updates FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE public.attachments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Permitir acesso completo em attachments" ON public.attachments;
CREATE POLICY "Permitir acesso completo em attachments" ON public.attachments FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE public.planning_items ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Permitir acesso completo em planning_items" ON public.planning_items;
CREATE POLICY "Permitir acesso completo em planning_items" ON public.planning_items FOR ALL USING (true) WITH CHECK (true);

ALTER TABLE public.planning_links ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Permitir acesso completo em planning_links" ON public.planning_links;
CREATE POLICY "Permitir acesso completo em planning_links" ON public.planning_links FOR ALL USING (true) WITH CHECK (true);

-- 3. ÍNDICES DE DESEMPENHO
---------------------------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_demands_school_id ON public.demands(school_id);
CREATE INDEX IF NOT EXISTS idx_demands_status ON public.demands(status);
CREATE INDEX IF NOT EXISTS idx_demands_priority ON public.demands(priority);
CREATE INDEX IF NOT EXISTS idx_demand_updates_demand_id ON public.demand_updates(demand_id);
CREATE INDEX IF NOT EXISTS idx_attachments_demand_id ON public.attachments(demand_id);
CREATE INDEX IF NOT EXISTS idx_users_email ON public.users(email);

